package com.leelo.model;

/**
 * A rich definition generated by AI for a vocabulary term.
 */
public record AiDefinition(
        String translation,
        String englishDefinition,
        String spanishDefinition,
        String englishExample
) {
    /**
     * Formats this definition as readable text for the translation area.
     */
    public String formatForTranslationArea() {
        StringBuilder sb = new StringBuilder();
        if (translation != null && !translation.isBlank()) {
            sb.append(translation.trim()).append("\n\n");
        }
        if (englishDefinition != null && !englishDefinition.isBlank()) {
            sb.append("📖 EN: ").append(englishDefinition.trim()).append("\n");
        }
        if (spanishDefinition != null && !spanishDefinition.isBlank()) {
            sb.append("📖 ES: ").append(spanishDefinition.trim()).append("\n\n");
        }
        if (englishExample != null && !englishExample.isBlank()) {
            sb.append("💬 Ejemplo: ").append(englishExample.trim());
        }
        return sb.toString().trim();
    }
}
